import{_ as e,o as d,c as o,a6 as a}from"./chunks/framework.Dtv7txdI.js";const u=JSON.parse('{"title":"Server Defaults","description":"","frontmatter":{},"headers":[],"relativePath":"v1/server/defaults.md","filePath":"v1/server/defaults.md","lastUpdated":1787648967000}'),r={name:"v1/server/defaults.md"};function c(i,t,s,l,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="server-defaults" tabindex="-1">Server Defaults <a class="header-anchor" href="#server-defaults" aria-label="Permalink to “Server Defaults”">​</a></h1><p>Every default value in one place. All of them are overridable — see <a href="./configuration/">Configuration</a>.</p><h2 id="zero-configuration" tabindex="-1">Zero configuration <a class="header-anchor" href="#zero-configuration" aria-label="Permalink to “Zero configuration”">​</a></h2><p>With <strong>no <code>nitr.toml</code> at all</strong>, Nitr:</p><ul><li>listens on <code>127.0.0.1:3000</code></li><li>runs <code>scripts/handler.lua</code></li><li>has no config script, so <code>nitr.cfg</code> is <code>nil</code></li><li>exposes the minimal standard library: <code>json</code>, <code>http</code>, <code>log</code>, <code>time</code>, <code>validate</code>, <code>base64</code>, <code>path</code>, <code>url</code></li><li>has no database, no templates, no static mount</li><li>serves <code>/healthz</code> and <code>/readyz</code></li><li>logs at <code>info</code> in human-readable text</li></ul><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nitr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # works in an empty directory with a scripts/handler.lua</span></span></code></pre></div><h2 id="top-level" tabindex="-1">Top level <a class="header-anchor" href="#top-level" aria-label="Permalink to “Top level”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>listen</code></td><td><code>127.0.0.1:3000</code></td></tr><tr><td><code>handler_script</code></td><td><code>scripts/handler.lua</code></td></tr><tr><td><code>config_script</code></td><td>unset</td></tr><tr><td><code>dev_mode</code></td><td><code>false</code></td></tr><tr><td><code>workers</code></td><td>number of CPU cores</td></tr><tr><td><code>max_streams</code></td><td><code>workers - 1</code> (at least 1)</td></tr><tr><td><code>trust_request_id</code></td><td><code>false</code></td></tr><tr><td><code>pidfile</code></td><td>unset</td></tr></tbody></table><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Violation</th></tr></thead><tbody><tr><td><code>max_body_bytes</code></td><td>1 MiB</td><td><code>413</code></td></tr><tr><td><code>max_header_bytes</code></td><td>16 KiB</td><td>connection rejected</td></tr><tr><td><code>max_uri_bytes</code></td><td>8 KiB</td><td><code>414</code></td></tr><tr><td><code>max_connections</code></td><td>1024</td><td>listener stops accepting</td></tr><tr><td><code>pool_wait_ms</code></td><td>5000</td><td><code>503</code> + <code>Retry-After</code></td></tr><tr><td><code>header_read_ms</code></td><td>30000</td><td>connection closed</td></tr><tr><td><code>body_read_ms</code></td><td>30000</td><td><code>408</code> + <code>Connection: close</code></td></tr><tr><td><code>max_form_parts</code></td><td>64</td><td><code>413</code></td></tr><tr><td><code>max_field_bytes</code></td><td>64 KiB</td><td><code>413</code></td></tr><tr><td><code>max_file_bytes</code></td><td>10 MiB</td><td><code>413</code></td></tr></tbody></table><h2 id="lua-sandbox" tabindex="-1">Lua sandbox <a class="header-anchor" href="#lua-sandbox" aria-label="Permalink to “Lua sandbox”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>stdlib</code></td><td><code>math</code>, <code>table</code>, <code>string</code>, <code>utf8</code>, <code>coroutine</code>, <code>package</code></td></tr><tr><td><code>io</code> / <code>os</code></td><td><strong>excluded</strong></td></tr><tr><td><code>memory_limit</code></td><td>8 MiB per state</td></tr><tr><td><code>exec_timeout_ms</code></td><td>30000</td></tr><tr><td><code>require</code></td><td>confined to the handler script&#39;s directory</td></tr><tr><td>native Lua modules</td><td>cannot be loaded</td></tr></tbody></table><h2 id="standard-library" tabindex="-1">Standard library <a class="header-anchor" href="#standard-library" aria-label="Permalink to “Standard library”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>[std] features</code></td><td><code>json</code>, <code>http</code>, <code>log</code>, <code>time</code>, <code>validate</code>, <code>base64</code>, <code>path</code>, <code>url</code></td></tr></tbody></table><p>Opt-in beyond that: <code>db</code>, <code>fetch</code>, <code>template</code>, <code>crypto</code>, <code>cache</code>, <code>dbg</code>, <code>env</code>.</p><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to “Database”">​</a></h2><p>Applied whenever a <code>[database]</code> section exists:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>journal_mode</code></td><td><code>wal</code></td></tr><tr><td><code>busy_timeout</code></td><td>5000 ms</td></tr><tr><td><code>synchronous</code></td><td><code>normal</code></td></tr><tr><td><code>foreign_keys</code></td><td><code>true</code></td></tr><tr><td><code>cache_size</code></td><td>−2000 KiB per connection</td></tr><tr><td><code>migrations_dir</code></td><td><code>migrations</code></td></tr></tbody></table><h2 id="cache" tabindex="-1">Cache <a class="header-anchor" href="#cache" aria-label="Permalink to “Cache”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>max_entries</code></td><td>10000</td></tr><tr><td><code>max_bytes</code></td><td>32 MiB</td></tr><tr><td><code>default_ttl</code></td><td>300 s (<code>0</code> = no expiry)</td></tr></tbody></table><h2 id="outbound-http-nitr-fetch" tabindex="-1">Outbound HTTP (<code>nitr.fetch</code>) <a class="header-anchor" href="#outbound-http-nitr-fetch" aria-label="Permalink to “Outbound HTTP (nitr.fetch)”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>allow_private_networks</code></td><td><code>false</code> (SSRF refused)</td></tr><tr><td><code>allowed_hosts</code></td><td>unset (any public host)</td></tr><tr><td><code>max_response_bytes</code></td><td>8 MiB</td></tr><tr><td><code>max_concurrent</code></td><td>8</td></tr><tr><td><code>max_per_request</code></td><td>32</td></tr><tr><td><code>connect_timeout</code></td><td>10 s</td></tr><tr><td><code>timeout</code></td><td>30 s</td></tr><tr><td><code>pool_max_idle_per_host</code></td><td>8</td></tr><tr><td><code>max_retries</code></td><td>5 (retries themselves are opt-in)</td></tr><tr><td><code>propagate_trace_context</code></td><td><code>false</code></td></tr></tbody></table><h2 id="http-behaviour" tabindex="-1">HTTP behaviour <a class="header-anchor" href="#http-behaviour" aria-label="Permalink to “HTTP behaviour”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>[compression] enabled</code></td><td><code>false</code></td></tr><tr><td><code>[compression] algorithms</code></td><td><code>br</code>, <code>gzip</code> (server order wins)</td></tr><tr><td><code>[compression] min_size</code></td><td>1024 bytes</td></tr><tr><td>precompressed <code>.br</code> / <code>.gz</code> sidecars</td><td>always served when present</td></tr><tr><td><code>[cors]</code></td><td>disabled until <code>origins</code> is set</td></tr><tr><td><code>[rate_limit]</code></td><td>disabled</td></tr><tr><td><code>[static]</code></td><td>disabled until <code>dir</code> is set</td></tr><tr><td><code>[static] mount</code></td><td><code>/</code></td></tr><tr><td><code>[static] spa</code></td><td><code>false</code></td></tr></tbody></table><h2 id="health-and-shutdown" tabindex="-1">Health and shutdown <a class="header-anchor" href="#health-and-shutdown" aria-label="Permalink to “Health and shutdown”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>[health] enabled</code></td><td><code>true</code></td></tr><tr><td><code>[health] liveness</code></td><td><code>/healthz</code></td></tr><tr><td><code>[health] readiness</code></td><td><code>/readyz</code></td></tr><tr><td><code>[health] bind</code></td><td>the main listener</td></tr><tr><td><code>[shutdown] grace</code></td><td>30 s</td></tr><tr><td><code>[shutdown] stream_grace</code></td><td>5 s</td></tr></tbody></table><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to “Logging”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>format</code></td><td><code>text</code></td></tr><tr><td><code>level</code></td><td><code>info</code> (<code>debug</code> in dev mode)</td></tr><tr><td><code>RUST_LOG</code></td><td>overrides <code>level</code></td></tr></tbody></table><h2 id="behaviour-nitr-provides-without-being-asked" tabindex="-1">Behaviour Nitr provides without being asked <a class="header-anchor" href="#behaviour-nitr-provides-without-being-asked" aria-label="Permalink to “Behaviour Nitr provides without being asked”">​</a></h2><p>Things that are simply on, with no key to enable them:</p><ul><li><code>HEAD</code> reuses the matching <code>GET</code> route with the body stripped.</li><li>A bare <code>OPTIONS</code> on a known path answers <code>204</code> with <code>Allow</code>.</li><li><code>405</code> (with <code>Allow</code>) when the path exists but the method does not.</li><li>Range requests: <code>206</code> / <code>416</code>, and <code>If-Range</code>.</li><li>Conditional requests: <code>ETag</code>, <code>Last-Modified</code>, <code>304</code>.</li><li>A request id per request (UUIDv7), echoed as <code>X-Request-ID</code>.</li><li>Binary-safe request and response bodies.</li><li>Multi-value response headers, <code>Set-Cookie</code> included.</li><li>Percent-decoded query strings and path parameters.</li><li>No Lua tracebacks in responses — unless <code>dev_mode</code> is on.</li><li>Per-request panic containment: the state is recycled, the process lives.</li></ul>',31)])])}const p=e(r,[["render",c]]);export{u as __pageData,p as default};
